quests[88711] = { id = 88711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlender Einfall: Giftstoffe und Pheromone", description = "Unsere Verbündeten in Azj-Kahet haben eine strategisch Position für den Angriff auf die Sureki gefunden.\n\nMeldungen zufolge sammeln unsere Feinde Giftstoffe, die ihre Kriegsmaschinen antreiben sollen.\n\nNutzen wir diese Gelegenheit, um ihren Nachschub zu unterbrechen und vielleicht sogar ihre Alchemie besser zu verstehen.", sourceObjective = "Helft den Strahlen der Flamme, die Streitkräfte der Sureki im Ungezähmten Tal zu zerschlagen.", completion = "Was auch immer die Sureki sammeln, wir müssen davon ausgehen, dass es nichts Gutes verheißt.\n\nVielleicht können unsere Sakraditen mit den Proben, die Ihr gefunden habt, einige Gegengifte herstellen.\n\nEure Hilfe wird stets geschätzt. Die Strahlen der Flamme leuchten heller dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[88750] = { id = 88750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
