quests[88774] = { id = 88774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Energie mehr" }
quests[88803] = { id = 88803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung zur rechten Zeit", description = "Seid gegrüßt, Champion.\n\nIch habe einen Weg gefunden, wie ich Euch in den Visionen weiterhelfen kann. Solltet Ihr meine Unterstützung brauchen, könnt Ihr mich über dieses Stundenglas rufen.\n\nIch werde ein Konstrukt bilden, das Euch in der Vision hilft.", sourceObjective = "Interagiert mit dem Stundenglas und lasst Euch von Soridormi helfen.", progress = "Ich hoffe, das hier wird Euch nützen.", completion = "Ihr könnt damit Hilfe für jedwede Vision herbeirufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88805] = { id = 88805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vernarbter Pfad durch die Zeit", description = "Alte Feinde kehren zurück und Kampfwunden reißen erneut auf.\n\nBesiegt diese Feinde und kehrt mit ruhmreichen Geschichten zurück.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Gibt es Neues an der Front?", sourceObjectiveStatus = "unverified-source-field" }
quests[88808] = { id = 88808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vernarbte Reise durch die Zeit", description = "Azeroth ruft nach Hilfe, Champion. Ihre Wunden des Krieges bluten immer noch. Geht nach Zandalar und Kul Tiras, um jene zu finden, die ihr Leiden verlängern wollen.\n\nVernichtet Eure Gegner in ihrem Namen und verteidigt Azeroth.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ich wusste, dass ich Euch diese Aufgabe anvertrauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[88818] = { id = 88818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenfeger" }
quests[88870] = { id = 88870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wohlwollend beim Bilgewasserkartell", description = "Ihr habt dem Bilgewasserkartell bisher gut geholfen. Weiter so.\n\nSprecht mit Rocco Ratschbumm, er wird sich um Euch kümmern.", sourceObjective = "Sprecht mit Rocco Ratschbumm im Schrottladen.", completion = "He, das ist für Euch.", sourceObjectiveStatus = "unverified-source-field" }
