quests[88903] = { id = 88903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Rachsucht", description = "Blut führt zu Blut, und das Gewicht der Gefallenen liegt in der Luft wie ein geflüsterter Fluch. Wer Zeuge Eures Zornes wird, spürt, wie dieser in seine Knochen kriecht und sie zu immer härteren Schlägen treibt, wobei sich Verzweiflung als Mut tarnt. Rachsucht beendet die Gewalt nicht, sondern gibt dem Sturm nur Nahrung.", sourceObjective = "Bringt die Gesichtslosenmaske der Rachsucht in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Rachsucht auf den Altar.", completion = "Ihr solltet bereit sein, dem Zorn Eurer Feinde zu begegnen, wenn Ihr diese Maske aufsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[88904] = { id = 88904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Es könnte alles sein" }
quests[88916] = { id = 88916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlender Einfall: Ende der Sureki", description = "Verlässliche Quellen haben enthüllt, dass die Sureki sich für einen erneuten Angriff sammeln. Nun bringen wir den Kampf zu ihnen!\n\nDie Strahlen der Flamme haben sich bei Faerins Vorstoß versammelt und bereiten sich darauf vor, gegen die Sureki-Streitkräfte vorzugehen, die sich im nördlichen Azj-Kahet zusammenziehen.\n\nSeid gewarnt, <Soldat/Soldatin>. Die Sureki in \"Ende der Arathi\" sind zahlreicher und mächtiger.\n\nSolltet Ihr Unterstützung benötigen, müssten unsere Sakraditen auf dem Feld mit Tränken ausgestattet sein, um Euch beizustehen.", sourceObjective = "Unterstützt die Strahlen der Flamme und zerschlagt die Truppen der Sureki am Ende der Arathi.", progress = "Wir dürfen nicht zulassen, dass sie an Stärke gewinnen. Wir müssen jetzt zuschlagen!", completion = "Viele Lampenanzünder und Soldaten haben ihr Leben auf dem Friedhof verloren, den sie \"Ende der Arathi\" nennen.\n\nIm Namen derer, die in der Dunkelheit verschollen sind, und jener, die hier an der Front kämpfen, danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[88945] = { id = 88945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlender Einfall: Rak-Zakaz", description = "Die nerubischen Verbündeten, die Ihr mit Lady Faerin in Azj-Kahet gewonnen habt, erweisen sich als einfallsreich... vorerst.\n\nLaut ihren Kundschaftern sammeln sich Sympathisanten der Sureki in Rak-Zakaz, um den Loyalisten ihrer gefallenen Königin bei ihren erneuerten Sturmangriffen zu helfen.\n\nSchließt Euch bei Faerins Vorstoß mit unseren Truppen zusammen und schneidet der gegnerischen Verstärkung den Weg ab!", sourceObjective = "Unterstützt die Strahlen der Flamme und zerschlagt die Truppen der Sureki in Rak-Zakaz.", completion = "Wir haben Glück, dass wir Euch hier unten haben.\n\nEs ist noch nicht lange her, dass wir Arathi uns kaum je so tief ins Innere von Azj-Kahet gewagt hätten. Doch nun sind wir hier.\n\nEure Taten in Rak-Zakaz dürften uns eine Verschnaufpause verschaffen und werden den nächsten Sturmangriff auf die Aegismauer hoffentlich hinauszögern.", sourceObjectiveStatus = "unverified-source-field" }
quests[88947] = { id = 88947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen von Lorenhall", description = "In den Tiefen gibt es noch mehr zu tun, {name}!\n\nTrefft mich in Dornogal. Es gibt viel zu bereden!", sourceObjective = "Trefft Euch mit Brann Bronzebart in Dornogal.", completion = "Schön, dass Ihr hier seid! Wir haben jede Menge zu bereden.", sourceObjectiveStatus = "unverified-source-field" }
