quests[88967] = { id = 88967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 100" }
quests[88974] = { id = 88974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biostabilität", description = "Apropos Eier, ich hab nachgesehen und Funke hat ihre jetzt gelegt. Dauert nicht mehr lange, dann werden die ersten Schlängelchen schlüpfen!\n\nTreffen wir uns wieder am Nest, dann können wir unseren ersten Schlangennachwuchs in K'aresh willkommen heißen.", sourceObjective = "Helft beim Ausbrüten der Schlängelchen.", completion = "Die Oase hat all meine Erwartungen übertroffen, {name}, und meine Erwartungen waren tatsächlich sehr hoch. Eure Hilfe war von unschätzbarem Wert.\n\nAls ich Euch im Schlund traf, hätte ich nie vermutet, dass wir am Ende hier landen würden. Um ehrlich zu sein, hatte ich erwartet, dass Ihr längst mehrfach gestorben wärt.\n\nWie auch immer, ich denke, wir haben fürs Erste alle Spezies für unser kleines K'aresh-Paradies, die wir brauchen.\n\nJetzt müssen wir uns nur darum kümmern, das Ökosystem zu stabilisieren und sicherzustellen, dass es auch gedeiht.", sourceObjectiveStatus = "unverified-source-field" }
quests[88975] = { id = 88975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreck für schlängelnde Schlangen", description = "Irgendwas hat die Schlangen schon wieder aufgebracht. Sie sind ganz verschreckt.\n\nWas haltet Ihr davon, sie mit meiner Flöte noch einmal zu besänftigen?", sourceObjective = "Besänftigt mit Hemets besänftigender Flöte 15 aufgebrachte Schlangen.", progress = "Das klingt wie herrliche Musik in meinen Ohren.", completion = "Danke, dass Ihr Euch darum gekümmert und nebenbei noch die ganze Oase unterhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[88976] = { id = 88976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung von K'aresh", description = "Es ist vollbracht. Allen Messungen zufolge ist das Ökosystem der Oase jetzt völlig stabil. Zwar wird es immer etwas geben, wo wir nachhelfen können, aber sie würde überleben, wenn wir uns jetzt zurückziehen würden. \n\nNehmt Euch etwas Zeit, um mit allen zu sprechen. Beglückwünscht sie. Gute Arbeit sollte immer anständig gewürdigt werden.\n\nKommt wieder zu mir, wenn Ihr fertig seid.", sourceObjective = "Sprecht mit Eurem Team in der Oase.", completion = "Unsere Arbeit hier stellt sicher, dass wir, nach allem, was bei der Biokuppel Adani passiert ist, K'aresh wiederaufbauen können.\n\nEs wird Zeit brauchen. Wirklich viel Zeit. Doch ich schätze, da macht es sich bezahlt, unsterblich zu sein, nicht wahr? Auch wenn es tausende von Jahren dauern sollte, wird meine Heimat wiederaufgebaut werden.\n\nHoffentlich werde ich auch zugegen sein, um es zu erleben. Ich habe eine Stasiskapsel, auf der Euer Name steht, falls Ihr sie brauchen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[88980] = { id = 88980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsjob?", description = "Mehr Schieferrückenessenz könnte nicht schaden. \n\nIch kann mir vorstellen, dass eine Gelegenheit, die Sande von K'aresh zu sichern, genau das Richtige für Euch wäre, hab ich recht? \n\nBringt mir einfach mit, was Ihr gefunden habt, wenn Ihr fertig seid.", sourceObjective = "Sammelt 10 Schieferrückenessenz im ungebundenen Raum von K'aresh.", progress = "Habt Ihr die Essenz?", completion = "Ausgezeichnet. Jetzt können wir mehr Schieferrücken erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88981] = { id = 88981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nestpflege", description = "Höchste Zeit, Funken, Indigo und dem Nest der Schlängelchen eine Abkühlung zu verschaffen. Unseren Schlangen auf K'aresh soll es schließlich an nichts fehlen.\n\nKeine Sorge, Ihr müsst nichts bis dorthin schleppen. Wir verwenden einfach wieder Ve'naris Portationsmarker - wie beim letzten Mal.", sourceObjective = "Kühlt das Nest der zwei genannten Schlangen und ihrer Schlängelchen ab.", completion = "Wunderbar! Freut mich, dass es ihnen gut geht. Eine zuckersüße, glückliche Familie.", sourceObjectiveStatus = "unverified-source-field" }
quests[89016] = { id = 89016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur für Mitglieder", sourceObjective = "Willkommen im Club! Egal, ob es Euch nach Spielen oder Schnetzeln ist, unser Bonusprogramm stattet Euch mit den edelsten Belohnungen aus, die das Garbagio zu bieten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[89018] = { id = 89018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammkunde: Silber", sourceObjective = "Ihr legt einen steilen Karriereaufstieg hin! Besorgen wir Euch eine Verbesserung!", sourceObjectiveStatus = "unverified-source-field" }
