quests[89023] = { id = 89023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammkunde: GOLDENE LEGENDE!!!", sourceObjective = "Das ist alles, was wir haben! Ihr habt den Gipfel der Welt erreicht, Schätzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89024] = { id = 89024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit ist Geld!", sourceObjective = "Jagt den Scheinen hinterher!", sourceObjectiveStatus = "unverified-source-field" }
