quests[89027] = { id = 89027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Essen", sourceObjective = "Ihr wollt das zum Mitnehmen? Wie Ihr wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[89028] = { id = 89028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markant", sourceObjective = "Das geht aufs Haus! Bringt das dem netten Hobgoblin gegenüber und sucht Euch was Feines aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[89029] = { id = 89029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markant", sourceObjective = "Mehr habe ich nicht! Sando wird sich darum kümmern, dass ihr aufgetakelt werdet. Aber vielleiiiicht könnt ihr einige mehr im Kasino finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[89039] = { id = 89039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turboschub: Ungeheure Herausforderungen", description = "<Lorenhall hat ein Problem. Wir brauchen Folgendes. Eine erprobte Truppe, oder meinetwegen einfach eine zusammengewürfelte Gruppe von Haudraufs, die bereit is', unseren Kumpels in Lorenhall zur Seite zu stehen. Helft mit, das größten Teil unserer Konkurrenten aus dem Weg zu räumen, und wir entlohnen Euch großzügig.\n\nSchließt die Aufgabe ab und holt Euch eine besondere Belohnung von Beraterin Wrexxel vor der Schatzkammer von Dornogal ab. Angebot für kurze Zeit. Einige Einschränkungen gelten.>", sourceObjective = "Bezwingt vier beliebige Bosse in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad \"Schlachtzugsbrowser\" oder höher oder schließt vier beliebige mythische Dungeons ab.", completion = "Danke, Kumpel. In Lorenhall geht's grad drunter und drüber. Wir sind für jede Hilfe dankbar.\n\nAlso, abgemacht is' abgemacht. Hier is', was wir Euch schulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89056] = { id = 89056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roch-Quetball, die Zweite", description = "Es ist wieder an der Zeit, die Reflexe unseres Jungtiers zu prüfen. \n\nVielleicht könntet Ihr noch einmal Roch-Quetball mit ihnen spielen?", sourceObjective = "Fangt einen Ball 10-mal, während Ihr mit Eurem Nekrorochenjungen spielt.", progress = "Ihr tut mir einen großen Gefallen damit, das Jungtier auf Trab zu halten.", completion = "Ah ja, wunderbar. Das Junge entwickelt sich prächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[89057] = { id = 89057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweifaroma", description = "{name}! Seid Ihr bereit für ein neues Dufterlebnis?\n\nIch habe eine neue Mischung für die Dornschweife zusammengebraut. Diese Charge ist auf jeden Fall besser als die letzte.\n\nWärt Ihr so gut und würdet sie für mich testen?", sourceObjective = "Besprüht 8 königliche Dornschweife mit Pheromonen.", completion = "Wie ich erwartet hatte. Besser als beim letzten Mal! Om'talad wird über diese Daten hocherfreut sein.\n\nIch mache mich gleich daran, die Formel noch weiter zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[89061] = { id = 89061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einzahlung bitte", description = "<Nachdem Ihr der Invasion der Verschlinger ein Ende gesetzt hattet, habt Ihr diesen festen Klumpen Anima aus dem Bauch ihres Anführers herausgezogen. \n\nVe'nari könnte damit vielleicht die Biokuppeln mit Energie versorgen.>", sourceObjective = "Bringt die kristallisierte Anima zu Ve'nari in der Oase.\n\nBereitgestellter Gegenstand:", completion = "Beeindruckende Beute. Ein noch beeindruckender Handel.\n\nIhr werdet dafür entlohnt werden. Ich will nicht in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89062] = { id = 89062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einzahlung bitte", description = "<Nachdem Ihr der Invasion der Verschlinger ein Ende gesetzt hattet, habt Ihr diesen festen Klumpen Anima aus dem Bauch ihres Anführers herausgezogen. \n\nVe'nari könnte damit vielleicht die Biokuppeln mit Energie versorgen.>", sourceObjective = "Bringt die kristallisierte Anima zu Ve'nari in der Oase.\n\nBereitgestellter Gegenstand:", completion = "Beeindruckende Beute. Ein noch beeindruckender Handel.\n\nIhr werdet dafür entlohnt werden. Ich will nicht in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89063] = { id = 89063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einzahlung bitte", description = "<Nachdem Ihr der Invasion der Verschlinger ein Ende gesetzt hattet, habt Ihr diesen festen Klumpen Anima aus dem Bauch ihres Anführers herausgezogen. \n\nVe'nari könnte damit vielleicht die Biokuppeln mit Energie versorgen.>", sourceObjective = "Bringt die kristallisierte Anima zu Ve'nari in der Oase.\n\nBereitgestellter Gegenstand:", completion = "Beeindruckende Beute. Ein noch beeindruckender Handel.\n\nIhr werdet dafür entlohnt werden. Ich will nicht in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89065] = { id = 89065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rochenrennen Richtung Zukunft", description = "Wir haben es wohl wieder mit einem übermütigen Nekrorochen zu tun! Wollt Ihr ihn müde machen?", sourceObjective = "Fordert den rasenden Nekrorochen zu einem Wettrennen heraus und erreicht die Ziellinie.", progress = "Passt nur auf, der da ist flink!", completion = "Mir tun die Knochen schon weh, wenn ich Euch nur so herumflitzen sehe!", sourceObjectiveStatus = "unverified-source-field" }
quests[89192] = { id = 89192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein harter Arbeitstag", description = "Unser Vorrat an Leerenschilden geht zur Neige. Eure Hilfe wird benötigt, um einen neuen herzustellen.\n\nTrefft mich außerhalb der Kuppel im Osten. Wir werden ihn gemeinsam herstellen.", sourceObjective = "Helft Ve'nari außerhalb der Oase dabei, einen Leerenschild herzustellen.", progress = "Kommt, lasst uns beginnen.", completion = "Eure Fähigkeit, mir die richtigen Gegenstände zuzuwerfen, ist wirklich nützlich. Ihr glaubt gar nicht, wie oft es den Leuten an dieser Fähigkeit mangelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[89194] = { id = 89194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für den Bienenboogie", description = "{name}, genau die {race}-Unterstützung, die ich gebraucht habe! Tanzt bitte für mi... Ich meine, für die Bienen.\n\nIch werde Euch hinterhersehen.", sourceObjective = "Tanzt für die Bienen in der Oase.", progress = "<Alaenra scheint still für die Bienen zu tanzen, zu einem Rhythmus, den nur sie hören kann.>", completion = "Die Bienen wissen zwar schon, wo die Pflanzen sind, aber eine kleine Erinnerungsstütze kann nicht schaden.\n\nAußerdem sehe ich Euch gerne beim Tanzen zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[89195] = { id = 89195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz schöner Summsinn", description = "Mir scheinen gerade die Bienenstichwörter ausgegangen zu sein, aber ich brauche trotzdem mehr Bienen aus dem Sturmsangtal. Wärt Ihr so nett und würdet mir welche bringen?", sourceObjective = "Saugt in Rosalindes Imkerhof im Sturmsangtal auf Azeroth 20 Honigbienen für K'aresh auf.", progress = "<Alaenra scheint saugende Geräusche zu machen, während sie einen imaginären Staubsauger hält.>", completion = "Wie immer weiß ich Eure Hilfe sehr zu schätzen. Was? Ich kann doch nicht immer einen Wortwitz reißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89197] = { id = 89197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rochenranch", description = "Ah, da seid Ihr ja. Ich muss nach den Nekrorochen sehen, sie medizinisch untersuchen. Und ich könnte Hilfe beim Einfangen gebrauchen. Vielleicht könntet Ihr mir assistieren?", sourceObjective = "Fangt 6 ruhige Nekrorochen ein und bringt sie zum Anbindepfosten bei Om'talad.", completion = "Danke. Für jemanden mit weniger Gliedmaßen seid Ihr auf jeden Fall koordinierter.", sourceObjectiveStatus = "unverified-source-field" }
quests[89198] = { id = 89198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialreinigung", description = "So ein Mist! Die K'arrocs sind schon wieder ganz schön aufgedreht.\n\nKönntet Ihr sie gründlich waschen, damit ihr natürliches Aroma wieder durchdringt?", sourceObjective = "Wascht 10 beherrschende K'arrocs.", completion = "Danke, Kumpel! \n\nHabt Ihr schon einmal daran gedacht, Euch auf Düfte zu spezialisieren? Euer Aroma ist wirklich stark!", sourceObjectiveStatus = "unverified-source-field" }
quests[89209] = { id = 89209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summen und Brummen", description = "Diese Bienen sind richtige Arbeitspferde - Arbeitsbienen? Sie sind Arbeiterbienen, also... Ach, entschuldigt meine Zerstreutheit.\n\nMehrere der Bienen haben sich überarbeitet. Könnt Ihr sie zum Bienenstock zurückbringen?", sourceObjective = "Sammelt 10 überarbeitete Honigbienen auf und bringt sie zu ihrem Bienenstock zurück.", progress = "Meine Güte! Die sind ja furchtbar emsig, findet Ihr nicht auch?", completion = "Fertig? Dann schwirrt ab!\n\nDas war ein Wortwitz! Nur ein Wortwitz!", sourceObjectiveStatus = "unverified-source-field" }
quests[89210] = { id = 89210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotografie ist die Königin aller Disziplinen", description = "Also dann, {name}. Nehmt die Kamera und den Film. Ist ja nicht Euer erstes Mal. Zeit für die Dokumentation!\n\nIch weiß, Ihr seid immer richtig emsig, aber jetzt müsst Ihr Euch sammeln.", sourceObjective = "Dokumentiert 15 Honigbienen und die Bienenkönigin.", progress = "Bienen zu fotografieren, ist wunderbar, wenn es jemand anderes macht.", completion = "Einfach bien-lich! Das Foto behalte ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[89212] = { id = 89212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königlicher Fotograf", description = "<Om'talad macht äußerst konzentriert mehrere Fotos von sich.>\n\nAh!{name}! Wir müssen unsere Aufzeichnungen über die Dornschweife aktualisieren.\n\nDiese Kamera, die ich gerade... getestet habe, scheint korrekt zu funktionieren. Bitte kümmert Euch um die Aktualisierung.", sourceObjective = "Dokumentiert 10 königliche Dornschweife.", progress = "<Om'talad scheint in einige Daten der Konsole vertieft zu sein und weicht Eurem Blick bewusst aus.>", completion = "Ihr habt meinen Dank hierfür. Vielleicht sollten wir in den Berichten an Ve'nari nichts von dieser Sache vorhin erwähnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89213] = { id = 89213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhenflüge", description = "Wir benötigen neue Fotos von den K'arrocs für unsere Aufzeichnungen. Bitte knipst ein paar für uns auf Euren Streifzügen durch die Biokuppel.", sourceObjective = "Dokumentiert 7 beherrschende K'arrocs.", completion = "Ausgezeichnet. Ihr habt ein echtes Talent für Bildaufnahmen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[89221] = { id = 89221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Verlaub geklaubt", description = "Heute bin ich aufgewacht und habe mir gedacht: \"Der Teller von {name} mit dem Essen für die Schoßkäfer war ausgezeichnet. Ich vermute, es würde ihnen gefallen, wenn {name} das noch einmal machen würde.\"\n\nWarum sorgt Ihr nicht dafür, dass das geschieht, hmm?", sourceObjective = "Sammelt 7 zerhackte Oasenpflanzen und platziert 3 Pflanzenteller.", progress = "Habt Ihr die Schoßkäfer schon gefüttert?", completion = "Danke, {name}. Ihr seid ein Blätterretter.", sourceObjectiveStatus = "unverified-source-field" }
quests[89222] = { id = 89222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überrest von Azeroth", description = "Auf den ersten Blick sieht es aus wie ein kristallisierter Splitter von Azeroths Lebensblut. Der Blick in den Splitter enthüllt Visionen von Kriegen an vertrauten Fronten, zahllose im Kampf gefangene Leben. Das Donnern tobender Stürme und brechender Wellen beginnt Euch zu überwältigen, bevor es unvermittelt verstummt.\n\nKul Tiras ruft nach Euch.", sourceObjective = "Bringt den Überrest von Azeroth zu Churbro in Boralus.", completion = "Ein Überrest von Azeroth aus einer Zeit voller Konflikte und Kampf. So ein geplagtes Artefakt hat in den Zeitwegen nichts verloren. Danke, dass Ihr es zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[89223] = { id = 89223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überrest von Azeroth", description = "Auf den ersten Blick sieht es aus wie ein kristallisierter Splitter von Azeroths Lebensblut. Der Blick in den Splitter enthüllt Visionen von Kriegen an vertrauten Fronten, zahllose im Kampf gefangene Leben. Das Donnern tobender Stürme und brechender Wellen beginnt Euch zu überwältigen, bevor es unvermittelt verstummt.\n\nZandalar ruft nach Euch.", sourceObjective = "Bringt den Überrest von Azeroth zu Churbro in Dazar'alor.", completion = "Ein Überrest von Azeroth aus einer Zeit voller Konflikte und Kampf. So ein geplagtes Artefakt hat in den Zeitwegen nichts verloren. Danke, dass Ihr es zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[89238] = { id = 89238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachuntersuchung", description = "Durch die Untersuchung der K'arrocs können wir viele medizinische Daten sammeln.\n\nBitte nehmt die Kondensationsscheibe, um sie für einen einfachen Transport zu schrumpfen, und sammelt die Kleinen ein.", sourceObjective = "Schrumpft und sammelt 8 beherrschende K'arrocs.", completion = "Ich danke Euch nochmals. Diese K'arrocs sind genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[89240] = { id = 89240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlaf ist die beste Medizin.", description = "Wir müssen nachsehen, wie sich die Dornschweife entwickeln. Wärt Ihr so freundlich, weitere Blutproben zu nehmen?\n\nIhr könnt die Pfeile wie zuvor benutzen, um sie einzuschläfern, und dann holt Ihr Euch den Pfeil mit dem Blut.", sourceObjective = "Sammelt 5 Blutproben von königlichen Dornschweifen.", progress = "Bitte berichtet über Eure Fortschritte.", completion = "Ausgezeichnete Arbeit. Ich werde sofort mit der Untersuchung dieser Proben beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89241] = { id = 89241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf, auf" }
quests[89242] = { id = 89242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will goldenen Schlamm!", description = "Unsere Hüter scheinen ihre Pflichten wieder einmal vernachlässigt zu haben.\n\nNehmt den Sauger. Beseitigt die Klumpen. Ich gebe Euch einen Anteil der Erträge.", sourceObjective = "Beseitigt 25 geronnene Klumpen in der Oase.", progress = "Wie steht es um Eure Bemühungen?", completion = "Ihr enttäuscht mich nie, {name}. Fast nie. Wie versprochen, ist hier Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[89250] = { id = 89250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchende Reifen", description = "<Nur wenige Dinge sind so berauschend wie unbändige Geschwindigkeit. Und nur wenige Dinge sind so angesehen wie der 99-G-Genickbrecher in Omi Talullahs Garage.\n\nMobber wird schon wissen, wie Euer Gefährt mit dem neuen Bauteil aufgemotzt werden kann.>", sourceObjective = "Sprecht mit Mobber, um Euren 99-G-Genickbrecher aufzumotzen.", completion = "Seid Ihr bereit, Euer Gefährt aufzumotzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89251] = { id = 89251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer Lauf!", sourceObjective = "Paula sagte, dass Ihr einen echt heißen Lauf hättet... Wie wäre es, wenn wir noch etwas mehr aufdrehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89252] = { id = 89252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braucht Ihr Starthilfe?", sourceObjective = "Da draußen geht es ganz schön hart zu, daher haben Euch Eure Freunde eine Aufmunterung geschickt. Im wahrsten Sinne des Wortes!", sourceObjectiveStatus = "unverified-source-field" }
quests[89254] = { id = 89254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knipser", description = "Die Bilder mit den Schoßkäfern waren ein voller Erfolg. Wir brauchen mehr für das Marketing.\n\nTut mir leid, {name}. In diesem Fall sind die Schoßkäfer mit Hüten gefragter als Ihr. Aber seid nicht traurig. Wenigstens werdet Ihr bezahlt und noch bekannter, nicht?\n\nJetzt knipst schon los.", sourceObjective = "Macht ein S.E.L.F.I.E. mit verschiedenen Schoßkäfern, die Hüte tragen.", progress = "Macht die Aufnahmen interessanter, indem Ihr Eure Garderobe wechselt.", completion = "Ausgezeichnet. Ich werde sie sofort wegschicken.\n\nEntfernt Euch nicht zu weit, {name}. Wir werden Eure scharfen Augen schon bald wieder benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89263] = { id = 89263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Anteil an der Beute", sourceObjective = "Ihr {name}? Habt Ihr etwas für mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[89274] = { id = 89274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der hässliche Spiegel" }
quests[89288] = { id = 89288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Rissbrecher Tza'akir" }
quests[89291] = { id = 89291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Eidbrecherin Desamirah" }
quests[89293] = { id = 89293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Beschattet" }
quests[89294] = { id = 89294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Übereinstimmende Ansichten" }
quests[89295] = { id = 89295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme lodert ewig", description = "Diese Sureki sind recht hartnäckig! Diese Hartnäckigkeit gilt es mit unseren Klingen zu begegnen.\n\nKönnen wir in den kommenden Kämpfen weiterhin auf Eure Unterstützung zählen?", sourceObjective = "Schließt das Szenario \"Nachtsturz\" ab.", completion = "Ihr habt einen Augenblick des Friedens für uns herausgeschunden.\n\nRuht Euch aus, doch achtet stets darauf, dass Eure Klinge geschliffen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[89297] = { id = 89297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Groß und wütend sind sie nicht mehr so niedlich", description = "Anscheinend gibt es Individuen, die Schoßkäfer adoptieren möchten. Adoptionen bedeuten mehr Einnahmen.\n\nWas wiederum der Oase zugutekommt. Bitte beschafft mir mehr Essenz.", sourceObjective = "Sammelt 10 Schoßkäferessenz im ungebundenen Raum von K'aresh.", progress = "Habt Ihr die Aufgabe erledigt?", completion = "Sehr gut, {name}. Eure Bemühungen sind so willkommen und notwendig wie immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[89317] = { id = 89317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinderwoche in Dornogal", description = "Oh, hallo! Ihr müsst {name} sein. Ich kann Euch nicht genug danken, dass Ihr mit den Kleinen geholfen habt.\n\nDa wir Irdenen keine eigenen Kinder haben, hielt ich es für eine spaßige Idee, einigen unseren Verbündeten für die Woche auszuhelfen. Doch wie sich herausstellt, sind Kinder sehr... energiegeladen. Ich verstehe auch noch nicht so richtig, was Kinder unter \"Spaß\" verstehen.\n\nWenn Ihr das Koboldkind mitnehmen könntet, wäre mir das eine große Hilfe. Es scheint da einen Ort zu geben, den es besuchen will.\n\nMit dieser Pfeife könnt Ihr es zu Euch rufen.", sourceObjective = "Sprecht mit dem Waisenkind Skibbles.", completion = "<Skibbles blickt Euch staunend an, dann scheint sie erst zu bemerken, wie sie starrt.>\n\nIhr seid viel größer als meine Kobold-Freunde. Hallo Langbein, ich heiße Skibbles!\n\nHabe gehört, Ihr seid sehr mutig, Langbein. Skibbles will sein wie Ihr! Felssprecher-Dame sagt, Ihr seid hier, um Skibbles zu helfen.\n\n<Skibbles schnappt übertrieben laut nach Luft. Sie reißt die Augen auf, als würde ihr plötzlich etwas einfallen.>\n\nSeid Ihr hier, um Skibbles auf ein Abenteuer mitzunehmen? Wollte schon immer auf ein Abenteuer gehen! Das wird der beste Tag überhaupt!", sourceObjectiveStatus = "unverified-source-field" }
quests[89318] = { id = 89318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mutiger Kobold", description = "Langbein! Die nette Felssprecher-Dame sagt, Skibbles darf heute machen, was sie will!\n\nNun, ich hab einen großen Traum. So groß, dass ich Ärger dafür bekomme. Oft.\n\n<Skibbles holt tief Atem.>\n\nIch will mutiger Kerzenritter werden, wie glitzernde Menschen mit den Schwebebooten!\n\nU-Und ich hab gehört, es gibt einen Kristall, der heller leuchtet als jede Kerze!\n\n<Skibbles verstummt, als rechnete sie schon mit einer Ablehnung.>\n\nWürdet... Ihr Skibbles zu den Kerzenrittern mit den großen Kätzchen bringen?", sourceObjective = "Bringt Skibbles nach Mereldar.", progress = "Oh, hallo, {name}. Ich hatte eine wundervolle Unterhaltung mit der Leitung dieses Waisenhauses. Nachdem ich den Kindern beim Spielen zugesehen habe, verstehe ich allmählich, warum meine bisherigen Aktivitäten nicht so spannend für die Kleinen unter meiner Aufsicht waren.\n\nSie scheinen kein großes Interesse an Stadtführungen zu haben, weisen dafür aber eine erstaunliche Fähigkeit auf, so zu tun, als ob! Faszinierend.\n\nOh, das hatte ich fast vergessen: Hattet Ihr die Gelegenheit, mit Skibbles die Lampenanzünder zu besuchen?", completion = "Du liebe Güte, ich habe Skibbles noch nie so aufgeregt gesehen! Es klingt so, als hätten die Lampenanzünder einen ziemlichen Eindruck bei ihr hinterlassen.\n\nWo wir gerade von Kindern sprechen, ich habe die anderen Arathikinder beim Spielen beobachtet und bemerkt, dass Destien mehr Interesse an diesem Buch als am Spiel mit den anderen Kindern zeigt.\n\nWürdet Ihr mit ihm sprechen? Es muss etwas geben, das er lieber tun würde, als hier zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[89319] = { id = 89319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wundersame Gewebe", description = "<Destien starrt auf seine Füße, als Ihr Euch nähert.>\n\nH-Hallo! Ich bin Destien. Die irdene Matrone Ullna hat mir von Euch erzählt und gesagt, Ihr seid <ein Abenteurer/eine Abenteurerin>! Ihr habt bestimmt schon viele gruselige und großartige Dinge gesehen, stimmt's?\n\nE-Es gibt da etwas, das ich gerne tun würde, aber ich habe Angst, dass es die Leute erschreckt.\n\n<Destien sieht sich nervös um und senkt die Stimme.>\n\nIch habe gehört, dass es liebe Neruber gibt und Ihr sie getroffen habt! Ich wollte schon immer mit einem reden, aber sie machen mir Angst.\n\nWürdet Ihr mich zu einem Treffen mit ihnen begleiten?", sourceObjective = "Bringt Destien zum Nest der Weberin, damit er die Witwe treffen kann.", progress = "Meine Güte! Die Neruber haben wahrlich eine interessante Gesellschaft. Die Jungen wirken ganz anders als die Kinder der Arathi, obwohl ihr Drang zum Spielen und Unfugtreiben ähnlich ist.\n\n<Ullna lächelt liebevoll.>", completion = "Seht Euch nur Destien an!\n\nIch kann mich nicht erinnern, dass er je so viel geredet hätte. Die Neruber müssen wirklich einen starken positiven Eindruck bei ihm hinterlassen haben. \n\nIch kann es kaum erwarten zu hören, was er während der gemeinsamen Zeit mit Euch heute alles gelernt hat. Wer weiß? Vielleicht ist das ein kleiner Beginn für ein besseres Verständnis der beiden Völker füreinander.\n\nOh! Das Neruberkind, Fadian, erwartet Euch schon gespannt. Er spricht noch nicht, wie es für junge Neruber üblich ist, aber er kommuniziert auf andere Weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[89320] = { id = 89320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eifrige Ingenieur", description = "<Fadian blickt Euch nervös an.\n\nEr hält eine Zeichnung hoch, die eine Goblinrakete darzustellen scheint, ähnlich dem Raketenbohrer nach Lorenhall.\n\nVielleicht möchte er gerne mit dem Raketenbohrer nach Lorenhall in den Schallenden Tiefen fahren?>", sourceObjective = "Seht Euch mit Fadian den Raketenbohrer in den Schallenden Tiefen an.", completion = "Seht Euch nur Fadian an! Ich weiß, wie stolz er auf diesen kleinen Bot ist, den er gebaut hat. Es freut mich also, dass er ihn an einen Ort bringen konnte, wo seine Talente geschätzt werden.\n\nIch werde hierbleiben und versuchen, mit Professor Neltik zu sprechen. Warum nehmt Ihr nicht Kitzy mit? Wir treffen uns in Dornogal wieder, sobald Ihr fertig seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[89321] = { id = 89321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erholung für Krähen", description = "He! Ihr seid {name}, stimmt's? Ich heiße Kitzy! Ich bin echt froh, Euch zu sehen.\n\nPasst auf, ich will wirklich dringend zurück an die Oberfläche, in die Steinstadt. Die Luft ist so sauber und die Sonne ist so hell!\n\nIch habe auch einen riesigen, blauen Vogel vorbeifliegen gesehen, aber der hatte so viele Beine! Ullna sagte, man nennt sie... Kree? Krähe? Irgendwie so.\n\nIch will jedenfalls eine sehen! Ich habe noch nie so was Schönes gesehen. Glaubt Ihr, ich darf eine streicheln?\n\n<Kitzy schnappt nach Luft, ihre Augen leuchten vor Aufregung.>\n\nGlaubt Ihr, ich darf auf einer REITEN?", sourceObjective = "Bringt Kitzy nach Dornogal, damit sie die Sturmkrähen sehen kann.", completion = "Kitzy hat was getan? Du liebe Güte, darauf wäre ich nie gekommen. Kinder sind wirklich erstaunlich. Ihre Verspieltheit und Kreativität scheinen grenzenlos zu sein.\n\nDiese Reise hat mir die Augen geöffnet. Ich glaube, ich verstehe Kinder jetzt ein wenig besser, nachdem ich mit den anderen Verwaltern gesprochen und all Eure Taten beobachtet habe.\n\nIch kann es kaum fassen, {name}. All diese Leute sind wegen Skibbles, Destien, Fadian und jetzt auch Kitzy gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89322] = { id = 89322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besseres Morgen", description = "{name}, seht nur! Alle diese Leute sind hier, um über die Zukunft der Kinder zu sprechen.\n\nSie haben auch den Wunsch geäußert, mit Euch zu sprechen.", sourceObjective = "Sprecht mit den kürzlich eingetroffenen Unterstützern.", progress = "Hattet Ihr schon Gelegenheit, mit den Unterstützern zu sprechen?", completion = "{name}, ich kann Euch nicht genug danken. Alle diese Kinder haben allem Anschein nach eine glänzende Zukunft vor sich, und Ihr habt einen großen Teil dazu beigetragen.\n\nDank Euch habe auch ich das Gefühl, ich verstehe Kinder ein wenig besser. Sie sind wirklich wundervoll, auch wenn sie manchmal ganz schön anstrengend sein können.\n\n\n\nIch weiß, Ihr seid sehr beschäftigt, aber ich hoffe, dass wir Euch auch im nächsten Jahr wiedersehen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[89323] = { id = 89323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheerte Lande", description = "Illidan lehrte uns, dass wir im Kampf mit Gefahren, die keine Grenzen kennen, bereit sein müssen, es ihnen gleichzutun. Mit seinem Zorn bändigte er die Macht der Teufelskraft und ich werde mit der Leere dasselbe tun.\n\nEin Splitter von dieser Welt, vom alles Verschlingenden berührt, befindet sich tief im Herzen von Nordsufaad. Mit der von Leona gesammelten Leerenessenz und diesem Splitter als Gefäß, werde ich die Macht der Leere meinem Willen unterwerfen.\n\nDie Stärke der Illidari mit den Geheimnissen der Ren'dorei zu kombinieren, wird mich unaufhaltbar machen.", sourceObjective = "Reist nach Nordsufaad.", progress = "Reist zum Standort des Splitters in Nordsufaad.", completion = "Seine Macht will entfesselt werden. Hört Ihr es nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[89324] = { id = 89324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Teil von etwas Größerem", description = "Findet die Relikthüter. Sie durchkämmen diese Abfälle wie Aasfresser, auf der verzweifelten Suche nach Stärke in den Beweisen der Schwäche ihres Volkes.\n\n<Adarus spuckt verächtlich in den Sand.>\n\nDas einzige wertvolle Objekt steht hier vor uns, und sie halten es aus Furcht unter Verschluss. Ich werde diesen Fehler nicht machen.\n\nGeht, findet diese Relikthüter, nehmt ihnen ihre Schlüssel ab, und kehrt zurück.", sourceObjective = "Besorgt die drei Schlüssel.", progress = "Ihr habt Euch bisher als nützlich erwiesen, {class}. Macht weiter so.", completion = "Behaltet das Bruchstück vorerst.\n\nIch werde es bald brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89325] = { id = 89325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenfluss der Leere", description = "Endlich, {name}. Mit der verheißungsvollen Macht dieses Bruchstücks und meiner Meisterschaft in den Künsten der Illidari werde ich mich der Schattenwache und allen anderen Gefahren stellen können, die die Leere uns entgegenwirft.\n\nLeona erwähnte eine Höhle in der Nähe von Shan'dorah, in der die Leerenenergien zusammenlaufen, die K'aresh durchdringen.\n\nTrefft uns dort und werdet Zeuge meines Aufstiegs.", sourceObjective = "Trefft Adarus und Leona am Ritualplatz in der Höhle bei Laacunas Bruch.", completion = "Wir sind fast bereit. Allerdings kann ich nicht anders, als mich zu fragen, ob Adarus sich nicht übernommen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[89326] = { id = 89326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destillierte Dunkelheit", description = "Adarus bereitet seinen Geist und Körper auf das Ritual vor.\n\nUnsere Aufgabe lautet, den Splitter an zwei Orten in diesem Höhlensystem aufzustellen. Dadurch wird der Kristall auf die Leerenenergie in der Umgebung abgestimmt, und es werden auch alle Leerenentitäten, die sich in der Nähe aufhalten, angelockt.\n\nBesiegt diese Entitäten, und der Splitter wird ihre Essenz absorbieren, wodurch er noch stärker wird.", sourceObjective = "Richtet den Splitter von K'aresh an der Leerenenergie in der Höhle aus.", progress = "Trödelt nicht, {name}. Zeit ist alles.", completion = "Gut gemacht. Ich übernehme ab hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[89327] = { id = 89327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos", description = "Wir sind da, {name}. Platziert den Splitter von K'aresh über Adarus und ich werde den Leerenköder, der Ramon'tas Leerenessenz enthält, in den Splitter kanalisieren.\n\nAdarus ist mächtig und entschlossen, aber was wir versuchen, ist sowohl experimentell als auch gefährlich.\n\nIch bitte Euch, wachsam zu bleiben.", sourceObjective = "Helft Adarus und Leona bei der Durchführung des Rituals.", progress = "Bereit, wenn Ihr es seid, {name}.", completion = "Ich hatte weder die Zeit noch die Konzentration, einen Zielort für das Portal auszuwählen, {name}. Er könnte überall sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[89331] = { id = 89331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenverstärkung", description = "Streitkräfte der Sureki sammeln sich in ganz Heilsturz und Azj-Kahet, doch wir halten sie für eine Ablenkung. Wir glauben, dass der Hauptangriff von Westen stattfinden wird.\n\nWenn die Zeit kommt, werden wir jede Hilfe brauchen, die wir bekommen können, um den Feind zurückzuwerfen und Mereldar zu verteidigen.\n\nKönnen die Strahlen der Flamme auf Eure Unterstützung zählen?", sourceObjective = "Schließt das Szenario \"Nachtsturz\" ab.", progress = "Macht Euch bereit, die Sureki können jeden Moment angreifen!", completion = "Ich wusste, dass wir uns auf Euch verlassen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[89332] = { id = 89332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainingslager", description = "Die Sureki sammeln sich in ganz Heilsturz und Azj-Kahet, während wir uns auf ihren Angriff auf Mereldar vorbereiten. Sie wollen unsere Kräfte spalten, doch wir dürfen ihre Aktivitäten an anderen Fronten nicht außer Acht lassen.\n\nEinheiten der Strahlen der Flamme wehren die Vorstöße des Feindes in Heilsturz ab, während wir gleichzeitig Azj-Kahet unterwandern.\n\nStoßt an der Front zu den Strahlen der Flamme und unterstützt sie dabei.", sourceObjective = "Schließt einen strahlenden Einfall oder einen Sureki-Einfall ab.", completion = "Der Heiligen Flamme sei Dank für Eure Unterstützung. Der Krieg geht weiter, doch wenigstens ist die Schlacht gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89343] = { id = 89343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungebundene Leere", description = "Die Reshiiwickel, die die Vorbotin Euch gegeben hat, ermöglichen es Euch, Euch für kurze Zeit in Energie zu verwandeln und in den ungebundenen Raum zu fallen. Das ist ein Alptraum für alle Astralen, eine natürliche Folge des Verlusts unserer Wickel und der Zerstrahlung unserer Energie. \n\nWir können den Prozess kontrollieren, indem wir uns richtig auf den Phasenleiter einstimmen. Auf diese Weise können wir diese Welt besuchen und unversehrt zurückkehren. So lautet zumindest die Theorie. Wir haben das bereits mit K'areshi-Phasentauchern getestet, aber noch nicht mit jemandem Eurer Art.\n\nSeid Ihr bereit, die Reise in den ungebundenen Raum zu riskieren?", sourceObjective = "Interagiert mit dem Phasenleiter, während Ihr die Reshiiwickel tragt.", progress = "Der ungebundene Raum ist schön für Besucher, aber gefährlich für jene, die darin gefangen sind.", completion = "Ihr lernt schnell. Gut. Der ungebundene Raum verschlingt die Narren und Tölpel.", sourceObjectiveStatus = "unverified-source-field" }
quests[89344] = { id = 89344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Euch nicht sieht", description = "Der ungebundene Raum ist ein arkanes Phänomen, das von Kreaturen der Leere verzerrt wird, die sich an seiner Energie laben. Wenn wir Astralen unsere Wickel beschädigen oder die Mittler ihre Anzüge, bleibt unsere Energie nicht lange intakt. Dann fallen wir in diese Ebene der Realität und kehren möglicherweise niemals zurück.\n\nDas Gute an diesem Albtraum ist aber, dass sämtliche Energie, die aus der Phase fällt, wertvoll ist. Benutzt den Phasenleiter, um den ungebundenen Raum zu betreten, und kämpft gegen die Beobachter, die sich an der dortigen Phasenenergie zu schaffen machen.", sourceObjective = "Tötet freigelassene Beobachter und sammelt die Phasenenergie im ungebundenen Raum bei der Zo'Shuulwarte ein.", progress = "Faszinierend, nicht wahr?", completion = "Habt Dank, {name}. Diese Raubtiere aus der Leere lauern uns auf und verbrauchen die Energie, die wir zur Versorgung der Biokuppeln verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89345] = { id = 89345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ungebundene Horror", description = "Die Raubtiere der Leere, die vor kurzem in den ungebundenen Raum eingefallen sind, machen uns deutlich weniger Probleme als die uralten Kreaturen, die vor langer Zeit hierhergereist sind. Diese urtümlichen Raubtiere ernähren sich von der Energie der Überbleibsel von K'aresh, ebenso wie der unglücklichen K'areshi, die in diesen Zustand verfallen sind.\n\nEine dieser Kreaturen, die wir den Nethertod nennen, sucht diesen Felsen heim. Wir konnten sie bisher nur vertreiben. Möglicherweise habt Ihr das Können, ihrer Herrschaft des Terrors ein Ende zu setzen?", sourceObjective = "Tötet Nethertod im ungebundenen Raum.", progress = "Habt Ihr den ungebundenen Raum von diesem Raubtier befreit?", completion = "Nethertod weilt nicht mehr unter uns. Unsere Erkundung des ungebundenen Raums kann weitergehen. Ich wusste, dass Ihr uns in unserem Unterfangen eine große Hilfe sein würdet, {name}.\n\nEs wäre uns eine Ehre, wenn Ihr die Erkundung mit uns fortsetzen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[89346] = { id = 89346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Anteil an der Beute" }
quests[89348] = { id = 89348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summ, summ, summ, Liebe summt herum", description = "In Ordnung. Ich bringe die Bienen zur Oase und treffe Euch dort.", sourceObjective = "Sucht Botanikerin Alaenra in der Oase auf.", completion = "Fangen wir damit an, den Bienen bei der Akklimatisierung zu helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[89349] = { id = 89349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stipendium der Strahlen der Flamme", sourceObjective = "Eure beispielhafte Hilfe ist nicht unbemerkt geblieben, {name}. Ich hoffe, dass diese Belohnung Euch gute Dienste leistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[89351] = { id = 89351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung von Lorenhall: Paarspalterei", description = "Wenn Ihr Big G ans Leder wollt, müsst Ihr ein paar Köpfe rollen lassen, und zwar bei ein und demselben Oger, um genau zu sein.\n\nMug'Zees Armee an Handlangern belagert die zwielichtigsten Hinterzimmer des Garbagio. Wenn Ihr den Pikturm sichern könnt, lade ich Euch und Eure Freunde dort gerne jederzeit ab.", sourceObjective = "Bezwingt Mug‘Zee, Wachleitung, in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Normal'.", completion = "Nette Prügelei, {name}, dann wollen wir uns mal den Raketenritt anschauen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[89352] = { id = 89352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung von Lorenhall: Paarspalterei", description = "Wenn Ihr Big G ans Leder wollt, müsst Ihr ein paar Köpfe rollen lassen, und zwar bei ein und demselben Oger, um genau zu sein.\n\nMug'Zees Armee an Handlangern belagert die zwielichtigsten Hinterzimmer des Garbagio. Wenn Ihr den Pikturm sichern könnt, lade ich Euch und Eure Freunde dort gerne jederzeit ab.", sourceObjective = "Bezwingt Mug'Zee, Wachleitung, in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Heroisch'.", completion = "Nette Prügelei, {name}, dann wollen wir uns mal den Raketenritt anschauen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[89353] = { id = 89353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung von Lorenhall: Paarspalterei", description = "Wenn Ihr Big G ans Leder wollt, müsst Ihr ein paar Köpfe rollen lassen, und zwar bei ein und demselben Oger, um genau zu sein.\n\nMug'Zees Armee an Handlangern belagert die zwielichtigsten Hinterzimmer des Garbagio. Wenn Ihr den Pikturm sichern könnt, lade ich Euch und Eure Freunde dort gerne jederzeit ab.", sourceObjective = "Bezwingt Mug'Zee, Wachleitung, in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.", completion = "Nette Prügelei, {name}, dann wollen wir uns mal den Raketenritt anschauen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[89380] = { id = 89380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine andere Welt", description = "Ich vertrete eine Gruppe innerhalb des Bunds, die eine gefährliche, aber lebenswichtige Aufgabe hat - Phasentauchen. Ich war bei der Zo'Shuulwarte, als die Vorbotin sich in Energie verwandelt hat. Phasentauchen ist so ähnlich, aber profitabler.\n\nDer Bund führt Phasentauchgänge durch, um unsere Energiereserven aufzustocken. Auf K'aresh ist Energie gleich Macht - und jetzt müssen wir mit der Schattenwache darum konkurrieren. Wir brauchen unbedingt die Hilfe von jemandem wie Euch.\n\nTrefft mich an der Zo'Shuulwarte, wenn Ihr interessiert seid. Natürlich werden wir Eure Dienste auch kompensieren.", sourceObjective = "Findet Shad'anis an der Zo'Shuulwarte auf K'aresh.", completion = "Danke, dass Ihr unser Angebot angenommen habt, {name}. Das ist gefährliche Arbeit, bei der Ihr die Grenzen unserer Realität überschreiten müsst. Aber mit Risiko kommt Profit und mit Profit können wir die Welt verändern.", sourceObjectiveStatus = "unverified-source-field" }
