quests[89404] = { id = 89404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitkrise", description = "Ihr erinnert Euch nicht mehr an mich?\n\nHmm, manchmal können Zeitreisen diese Nebenwirkung haben.\n\nWie gut, dass ich mich liebend gern vorstelle.\n\nLasst mich erklären, was wir hier tun.", sourceObjective = "Sprecht mit Moratari und sucht dann Khadgar auf.", progress = "Khadgar braucht Eure Hilfe.", completion = "{name}! Ihr seid mir sehr willkommen an diesem finsteren Tag. Unser Teleportationszauber ist fehlgeschlagen und jetzt fällt die Legion in Dalaran ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[89405] = { id = 89405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straßengesindel", description = "Der Rest des Rats und ich haben uns derzeit in der Kammer des Wächters verbarrikadiert, um an einer Lösung zu arbeiten.\n\nIn der Zwischenzeit könnten wir Eure Hilfe dabei gebrauchen, die Legion ein wenig von uns abzulenken, damit wir nachdenken können.\n\nKommt zu mir in der Kammer des Wächters, sobald Ihr uns genug Zeit erkauft habt, um die Situation richtig abzuschätzen. Dann können wir das Blatt wenden und die Legion in die Defensive zwingen.", sourceObjective = "Befreit Dalaran von Dämonen.", progress = "Dalaran könnte ein paar Dämonen weniger vertragen.", completion = "Ich grüße Euch, {name}. Hervorragende Arbeit. Ihr habt uns gerade lang genug den Rücken freigehalten, dass wir dieses Chaos Herr werden konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[89406] = { id = 89406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr kommt hier nicht rein", description = "Die Bürger von Dalaran haben sich hinter magischen Barrieren verschanzt, die die Legion für den Moment in Schach halten. Die Macht dieser Barrieren ist jedoch nicht unerschöpflich.\n\nNehmt meinen Verstärkungsring und verstärkt die Barrieren, um unsere Leute zu beschützen. Das verschafft mir Gelegenheit, dem Ursprung dieser Legionsinvasion nachzugehen.\n\nDezimiert die Legion weiter, sobald Ihr fertig seid. Ich melde mich, sobald ich mehr in Erfahrung bringen konnte.", sourceObjective = "Verstärkt 5 magische Barrieren.", progress = "Die verstärkten magischen Barrieren sollten die Legion zurückhalten, bis Khadgar eine Lösung für diese Situation findet.", completion = "Das finde ich ganz wunderbar!\n\nIhr seid die perfekte Kontrollgruppe, um unsere Theorien zur Bedeutung von Artefakten für den Fluss der Zeitlinien auf die Probe zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89407] = { id = 89407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebrauchtwarensammlung", description = "Wenn wir Khadgar, Dalaran und unserem Experiment helfen wollen, dann müssen wir Euch ein Artefakt verschaffen.\n\nGlücklicherweise habe ich bereits einen Plan.\n\nDalaran steckt derzeit randvoll mit allerhand Gegenständen von temporaler Bedeutung, sogenannten Epochenobjekten. Wir sammeln ein paar, die niemand vermissen wird, geben der Legion die Schuld an ihrem Verschwinden und nutzen sie, um Euch ein Artefakt zu besorgen.\n\nHier. Ich habe eine Einkaufsliste für Euch.", sourceObjective = "Beschafft die staubige Steintafel, die verbogene und abgenutzte Klinge sowie die kuriose Kuriosität für Momentus.", progress = "Diese Objekte strotzen vor Bedeutsamkeit für die Epochen.", completion = "Eine hervorragende Sammlung von Epochenobjekten.", sourceObjectiveStatus = "unverified-source-field" }
quests[89408] = { id = 89408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fadenscheinig", description = "Um Euch ein Artefakt zu beschaffen, werden wir Temporalenergie brauchen.\n\nNormalerweise nutzen wir ewige Umhänge aus Zeitfäden, die sind in dieser Zeitlinie aber zerfasert. Ihr müsstet also stattdessen diese zerfaserten Zeitfäden in ganz Dalaran sammeln.\n\nIhr werdet sehen, wie sie hier und da erscheinen und wieder verschwinden. Sie sehen wie strahlende goldene Machtkugeln aus. Ihr könnt sie gar nicht übersehen.\n\nBringt sie her, sobald Ihr genug davon habt.", sourceObjective = "Sammelt zerfaserte Zeitfäden auf den Straßen von Dalaran.", completion = "Diese Fäden enthalten Spuren potenzieller Epochenenergie. Um ihre Macht erschließen zu können, müssen wir sie in ein stabilisierendes Material einsetzen, wie etwa ewige Bronze, und darin verankern.\n\nDabei geht etwas von ihrer Kraft verloren, aber für unsere Zwecke wird es reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89409] = { id = 89409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Bronze", description = "Nachdem wir nun die stabilisierenden Materialien und zerfaserten Fäden haben, können wir mit der Arbeit beginnen.\n\nMir ist es allerdings verboten, direkt mit dieser Zeitlinie zu interagieren. Ihr werdet mir also Eure Hände leihen müssen. Keine Sorge, es hält mich nichts davon ab, Euch Anweisungen zu geben.\n\nGeht nebenan an die Schmiede im \"Plattenladen\", dann fangen wir an.", sourceObjective = "Schmiedet ewige Bronze.", progress = "Ewige Bronze, ein Material voller Potenzial.", completion = "Nachdem Ihr nun ewige Bronze habt, können wir Euch ein Artefakt beschaffen, um unsere Tests durchzuführen.\n\nDann werdet Ihr kein Problem damit haben, Eurer Legende gerecht zu werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[89411] = { id = 89411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es fliegen die Fetzen", description = "Momentus vielleicht Experte für Dinge machen, aber Erus Experte für Dinge kaputtmachen!\n\n<Erus hebt das Wort \"kaputt\" besonders hervor, indem er mit seiner Faust auf seine Handfläche schlägt.>\n\nGeht. Tötet Dämonen. Nehmt Rüstungsfetzen. Dann wir Sachen zerlegen!\n\nIch sehr gern zerlegen.", sourceObjective = "Erbeutet die Überreste einer Legionsrüstung von den Dämonen rund um Dalaran.", progress = "Der Müll eines Dämons ist die Bronze des ewigen Drachen.", completion = "Gut. Gut. Ihr gut gemacht. Artefakt stärker werden. Fast so stark wie Erus.\n\n<Erus lacht über seine eigene Prahlerei.>", sourceObjectiveStatus = "unverified-source-field" }
quests[89412] = { id = 89412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torschlusspanik", description = "Khadgar ist nah dran, den Grund ausfindig zu machen, warum die Legion hier ist. Aber wenn niemand die Pläne der Legion durchkreuzt, ist nicht garantiert, dass er es auch schafft. Dalarans Schicksal ist noch nicht entschieden. Er braucht nur ein wenig mehr Zeit.\n\nIhr könnt ihm diese Zeit erkaufen, indem Ihr den Bemühungen der Legion hier in der Stadt Einhalt gebietet.\n\nSucht nach Legionsportalen und versiegelt sie. Das sollte den Fluss der in die Stadt strömenden Dämonen verlangsamen.", sourceObjective = "Versiegelt Legionsportale in Dalaran.", completion = "Ich spüre die Macht, die Euer Artefakt verströmt, schon von hier. Gut.\n\nIch habe mir weiterhin notiert, dass es durch die Machtnutzung noch nicht zersprungen ist. Das ist ebenfalls gut.\n\nLasst mich das eben für Morataris Aufzeichnungen notieren. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[89413] = { id = 89413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obliterativer Prozess", description = "Artefakt nicht Blick von Erus auf sich lenkt. Nein. Ihr habt dämonische Rüstungsfetzen.\n\nIhr jetzt vielleicht denkt, \"aber Erus, dämonische Rüstungsfetzen sind Abfall\", und Ihr vielleicht recht haben. Aber Erus sieht Dämonenfetzen und sieht nicht Abfall, sondern Bronze. Bronze im Abfall versteckt.\n\nPasst auf, Erus lehrt Euch, wie Ihr den Auflösungssand benutzen. Ihr legt Abfall in Sand, Sand löst ihn auf, Ihr bekommt Bronze aus der Asche.\n\nProbiert es. Benutzt den Auflösungssand und werft Überreste einer Legionsrüstung hinein.", sourceObjective = "Setzt die Fähigkeit 'Auflösungssand' ein, um Auflösungssand zu beschwören, und platziert dann die Überreste einer Legionsrüstung in dem Auflösungssand, um sie in Bronze zu verwandeln.", progress = "Viel Spaß beim Zerlegen!", completion = "Ihr Bronze auf dem Ewigen Basar ausgeben und viele schöne Dinge erhalten.\n\nWenn Ihr findet Abfall, einfach Auflösungssand beschwören.\n\nMüll rein, hübsche Bronze raus.\n\nPraktisch, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[89414] = { id = 89414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau zum richtigen Momentus", description = "Alles läuft wunderbar, {name}. Mit Eurem Artefakt solltet Ihr Khadgar helfen können, die Legion vollständig aus Dalaran zu vertreiben.\n\nMorataris Berechnungen zufolge sollte er den Ursprung der Legionsinvasion mittlerweile ausfindig gemacht haben. Kehrt in die Kammer des Wächters zurück, wenn Ihr bereit seid, und seht, was er herausgefunden hat.", sourceObjective = "Sprecht mit Khadgar in der Kammer des Wächters.", completion = "Es war ein harter Tag, {name}, aber bald wird unsere Entschlossenheit belohnt werden.\n\nNachdem Ihr die Legion mit Euren Heldentaten gerade zur rechten Zeit abgelenkt habt, konnte ich meine arkane Macht fließen lassen und den Strippenzieher hinter der Legionsinvasion in unserer geliebten Stadt ausfindig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89415] = { id = 89415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in die Zitadelle", description = "Teufelslord Nezmet konnte sich unserem Teleportationszauber entziehen und Risse in unseren Zauberschutzen öffnen.\n\nWenn ihm niemand das Handwerk legt, vergrößert Nezmet diese Risse, bis die Zauberschutze versagen und die Legion auf uns einstürmt.\n\nWir haben jetzt eine Gelegenheit, ihm den Garaus zu machen, bevor er es mit uns tut. Ohne ihren Anführer wird der Rest der Legion fallen.\n\nBegebt Euch so schnell wie möglich zur Violetten Zitadelle. Wir haben keine Zeit zu verlieren.", sourceObjective = "Tötet Teufelslord Nezmet.", progress = "Nezmet ist tot. Dalaran ist gerettet.", completion = "Wir ergänzen uns gut, {name}.\n\nDie Kirin Tor werden sich um die verbleibenden Streitkräfte der Legion kümmern. Ich muss meine Aufmerksamkeit darauf lenken, die volle Kraft der Zauberschutze wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89416] = { id = 89416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Dankbarkeit", description = "Seht Euch nur einmal an, wie Ihr Dalaran rettet. Ihr fangt schon an, Eurer Legende zu entsprechen.\n\n<Moratari sieht sich um, um erst sicherzustellen, dass Ihr wirklich allein seid.>\n\nWir müssen anderswo hin und andere treffen.\n\nIch öffne ein Portal zum Ewigen Basar.\n\n<Moratari denkt einen Moment über den Namen nach.>\n\nDort können wir gefahrlos im Freien miteinander sprechen, ohne die Zeitlinie zu beeinflussen. Geht einfach hindurch, sobald Ihr bereit seid.", sourceObjective = "Geht durch das Portal und trefft Eternus und den ewigen Drachenschwarm.", completion = "Moratari hat mich über Eure Unternehmungen in dieser Zeitlinie auf dem Laufenden gehalten, {name}.\n\nWisset, dass ich zufrieden bin.\n\nDalaran wird sich mit der Zeit erholen. Apropos: Ich werde die Zeitlinie beschleunigen, bis die Aufräumarbeiten abgeschlossen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[89417] = { id = 89417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Kennenlernen", description = "So, Dalaran ist wieder so, wie es sein soll.\n\nIhr habt gewiss viele Fragen, {name}. Wer sind wir? Was tun wir hier? Warum seid Ihr hier?\n\nDie einfache Antwort lautet: Wir sind der ewige Drachenschwarm, wir suchen in der Zeit Antworten auf Fragen, die unser aller Horizont übersteigen, und wir brauchen dazu Eure Hilfe.\n\nIch denke, diese Antwort wird Euch vielleicht eher begreiflich, wenn Ihr den Rest unseres Schwarms kennenlernt. Moratari, würdet Ihr bitte das Vorstellen übernehmen?", sourceObjective = "Seht Euch auf dem Ewigen Basar um.", progress = "Der ewige Drachenschwarm ist ganz schön zahlreich vertreten.", completion = "Wie Ihr seht, umfasst der ewige Drachenschwarm viele Denker, {name}. Sie alle arbeiten an Antworten auf recht dringende Fragen.\n\nWelches Wissen können wir erlangen, um uns auf noch größere Bedrohungen vorzubereiten?\n\nHätten wir triumphiert, wenn es noch schlimmer gewesen wäre?\n\nWelche Auswirkungen hat es, dass Sargeras sein Schwert in Azeroth gerammt hat, und haben die Artefakte Azeroth gerettet oder war es etwas anderes?\n\nÄh, ich meinte... Vergesst, dass ich etwas gesagt habe. Welches Schwert noch mal?", sourceObjectiveStatus = "unverified-source-field" }
quests[89418] = { id = 89418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fixer Zeitpunkt", description = "Mittlerweile sollte die Legion komplett aus Dalaran vertrieben worden sein. Ereignisse werden beginnen, sich abzuspielen. Ereignisse, die Eure Anwesenheit erfordern, {name}.\n\nMoratari wird Euch zurück zu Krasus' Landeplatz bringen. Dort wird Eure Legende weiter anwachsen.\n\nIch sehe großes Potenzial in Euch, {name}. Ganz gleich, aus welcher Zeitlinie Ihr stammt.", sourceObjective = "Sprecht mit Moratari und kehrt zu Krasus' Landeplatz zurück.", completion = "Hier sind wir nun. Zurück an der Stelle, an der alles begann.\n\nGleich wird jemand nach Euch suchen und Eure Legende wird ihren Anfang nehmen.\n\n<Moratari strahlt Euch aufgeregt an.>\n\nSeid Ihr nicht schon gespannt? Ich bin es auf jeden Fall.\n\nAch, und falls Ihr etwas braucht, kommt einfach beim Ewigen Basar vorbei. Wir warten immer.\n\nViel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[89450] = { id = 89450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstellt eine Nachbarschaft", description = "Ihr wisst ja, wie man sagt: Es braucht eine ganze Nachbarschaft!\n\nSagt man das nicht? Sollte man aber.\n\nHolt Euch die Unterschriften von gleichgesinnten Siedlern und gründet damit Eure eigene Nachbarschaft.", sourceObjective = "Sammelt Satzungsunterschriften von Spielercharakteren, um Eure neue Nachbarschaft zu gründen!\n\nBenutzt den Questgegenstand \"Nachbarschaftssatzung\", um Eure Satzung zu öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89464] = { id = 89464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Allgemein", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDas hier ist eine allgemeine Untersuchung, also könnt Ihr Euch Eure Kampfgegner frei aussuchen, damit wir Grundwerte für Eure Fähigkeiten bekommen.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 200 Gegner.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89465] = { id = 89465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Keine Aufgabe zu gering", description = "Heldentaten sind eine Frage der Perspektive. Was <einem mächtigen Helden/einer mächtigen Heldin> wie Euch banal erscheint, könnte für jemand anderen die Welt verändern.\n\nSucht Bedürftige auf und helft ihnen bei den Aufgaben, die sie für wichtig erachten. Dies wird Eure Legende wachsen lassen.", sourceObjective = "Schließt 6 Quests ab.", completion = "Euer Name geistert in den Köpfen der Leute herum und ist am Lagerfeuer in aller Munde. Je mehr Eure Legende wächst, desto mächtiger wird Euer Name. Aber kann die Macht eines Namens die Macht des dazugehörigen Artefakts überschatten? Das ist die alles entscheidende Frage.", sourceObjectiveStatus = "unverified-source-field" }
quests[89466] = { id = 89466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Lichtbresche", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf mächtigen Widerstand stoßen.\n\nFindet Mitstreiter, die Euch in der Lichtbresche helfen.", sourceObjective = "Schließt den Flügel 'Lichtbresche' von Antorus, dem Brennenden Thron auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89467] = { id = 89467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Verbotener Abstieg", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch im Verbotenen Abstieg helfen.", sourceObjective = "Schließt den Flügel 'Verbotener Abstieg' von Antorus, dem Brennenden Thron auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89468] = { id = 89468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Dungeonerkunder gesucht (Normal)", sourceObjective = "Schließt mithilfe des Dungeonbrowsers einen beliebigen Dungeon auf dem Schwierigkeitsgrad 'Normal' ab.", progress = "Angst ist zu erwarten, doch Ergebnisse sind notwendig. Sucht Euch eine Gruppe und stellt Euch den Schrecken. Wenn schon nicht für mich, dann für Moratari und die Daten.", completion = "Ihr habt ja keine Ahnung, wie sehr das Moratari freuen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[89469] = { id = 89469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Dungeonerkunder gesucht (Heroisch)", description = "Einige Orte sind selbst in guter Gesellschaft gefährlich. Zum Überleben braucht Ihr großartige Gesellschaft.\n\nVersammelt einige Zeitläufer um Euch und sucht nach Konzentrationen der Macht, denen Ihr allein nicht gewachsen wärt. Dann erstattet Bericht... falls Ihr überlebt.", sourceObjective = "Schließt mithilfe des Dungeonbrowsers einen beliebigen Dungeon auf dem Schwierigkeitsgrad 'Heroisch' ab.", progress = "Angst ist zu erwarten, doch Ergebnisse sind notwendig. Sucht Euch eine Gruppe und stellt Euch den Schrecken. Wenn schon nicht für mich, dann für Moratari und die Daten.", completion = "Ihr habt ja keine Ahnung, wie sehr das Moratari freuen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[89476] = { id = 89476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung" }
quests[89490] = { id = 89490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Arkanahetzer So'zer", description = "Arkanahetzer So'zer ist für eine Reihe von Diebstählen in Tazavesh verantwortlich, bei denen magische Relikte, Zauberstäbe und mehrere Kisten mit hochgradig giftigen Zo'kitafrüchten abhandengekommen sind.\n\nInformanten zufolge soll So'zer sich offenbaren, wenn ihm ein hochwertiges arkanes Relikt vor die Nase gesetzt wird.\n\nFertigt einen Gegenstand, der Versuchung genug ist, diesen Verbrecher aus seinem Versteck zu locken.", sourceObjective = "Kombiniert eine arkanes Runensiegel mit einem aufgeladenem Kristall und einem Zeichen des Schmugglers, um einen arkanen Köder zu fertigen und So'zer anzulocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[89492] = { id = 89492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Durchtriebene Duos in der Kuppel!", description = "Ganz richtig, die Durchtriebenen Duos sind hier!\n\nBeweist Eure Unterstützung! Sprecht mit Xyggie Marou in Dornogal und meldet Euch für eine Partie \"Durchtriebene Duos\" an.\n\nWartet danach, bis Ihr aufgerufen werdet, und los geht's! Zeigt ihnen, was Ihr draufhabt, <Held/Heldin>!", sourceObjective = "Besiegt die Durchtriebenen Duos und sprecht anschließend mit Vinnie Naschkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[89493] = { id = 89493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Feld", sourceObjective = "Willkommen, Kadett! Gut, dass Ihr hier seid.\n\nJetzt ist die Zeit gekommen: Begebt Euch in die Schlacht. Bekämpft die Sureki mit allem, was Ihr habt. Wir zählen auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[89494] = { id = 89494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfe machen Kleider", sourceObjective = "{name}! Schön, dass Ihr es einrichten konntet. Ich möchte Euch förmlich zu Eurer neuen Position in unseren Rängen gratulieren.\n\nIhr habt sie Euch mehr als verdient. Die Tapferkeit und die Eigenschaften, die Ihr zur Schau gestellt habt, verheißen viel für Eure zukünftigen Dienste im Namen der Strahlen der Flamme.\n\nNehmt daher bitte diesen Wappenrock an und tragt ihn bei Euren kommenden Vorhaben. Wir freuen uns darauf, Euch auf dem Schlachtfeld zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89496] = { id = 89496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger der Heiligen Flamme", sourceObjective = "In unserem Kampf gegen die Sureki habt Ihr Euch wahrlich bewährt, {name}.\n\nEuer Mut und Eure Bereitschaft, die Heilige Flamme zu verteidigen, sind bemerkenswert. Euer Kampfgeschick hat das Blatt auf dem Felde häufiger gewendet, als ich es zählen konnte.\n\nDafür belohne ich Euch mit diesem Wappenrock. Bitte nehmt ihn als Emblem und Anerkennung für Eure unermüdliche Beharrlichkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[89501] = { id = 89501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeladener Kristall", description = "Einen arkanen aufgeladenen Kristall werdet Ihr in K'aresh nicht finden, doch es gibt Wege, einen herzustellen!\n\nIch kenne jemanden, der Euch dabei helfen kann, arkane Energie zu ernten und speichern. Kommt mit dieser Energie und einem ungeladenem Kristall zu mir zurück, dann können wir ihn aufladen.\n\nBeansprucht die Hilfe von Myi Koo und reist anschließend durch das astrale Portal zum Azurblauen Gewölbe. Besorgt den Kristall und die Energie dort.", sourceObjective = "Trefft Euch mit Myi Koo, betretet die Tiefe \"Archivangriff\" und sammelt 6 arkane Energieproben und einen ungeladenen Kristall.", progress = "Habt Ihr den Kristall und die benötigte Energie gefunden?", completion = "Myi Koo ist voll geladen mit arkaner Energie. Mehr als genug, um einen Kristall aufzuladen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89502] = { id = 89502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Nachtsturz", description = "Die verbleibenden Sureki ziehen durch Heilsturz und Azj-Kahet, doch wir glauben, dass sie Truppen westlich der Ehrengründe zusammenziehen, damit sie Mereldar direkt angreifen können!\n\nBitte helft den Strahlen der Flamme bei der Verteidigung und schaltet die Bedrohung durch die Sureki aus!", sourceObjective = "Schließt das Szenario \"Nachtsturz\" ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[89505] = { id = 89505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Schmugglers", description = "Ein rechtschaffener Bürger wie Om'sto hat ganz sicher keines dieser illegalen Zeichen des Schmugglers.\n\nDoch wenn ich eines in die Finger bekommen könnte... dann wäre ich gewillt, es jemandem zu überlassen, dem ich etwas schuldig bin.\n\nWenn Ihr mir einen Gefallen tun würdet, wäre ich Euch etwas schuldig.\n\nReist nach Nordsufaad und füllt meine Tasche mit Dingen, die ich dort verloren habe. Wenn Ihr das tut, habe ich möglicherweise, was Ihr braucht.", sourceObjective = "Findet genug verlorene Gegenstände in Nordsufaad, um Om'stos Tasche zu füllen.", progress = "Konntet Ihr alle meine Gegenstände bergen?", completion = "Wie versprochen werde ich diese Schuld mit dem Zeichen begleichen, das Ihr benötigt. Auf einen Gegenstand aufgebracht belegt das Zeichen, dass die Transaktion von den Kartellvertretern abgesegnet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[89514] = { id = 89514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Verstörende Visionen erneut erlebt", description = "Dieses Schwarzblut, das die Neruber verdorben hat, ist ein übles Zeug.\n\nMeines Wissens haben die Alten Götter dieses Blut schon einmal eingesetzt.\n\nSoridormi von den Bronzedrachen ist zum ersten Mal in Dorgogal und hat eine Methode ersonnen, wie Ihr dieses Ereignis aus der Vergangenheit nachvollziehen könnt.\n\nSucht sie auf, um diese verstörenden Visionen zu erleben, und erfahrt, was Ihr könnt.\n\nHaltet die Augen offen, {name}. Alle Hinweise, die Ihr mitnehmt, werden uns heute helfen.", sourceObjective = "Besiegt 5 Bosse in \"Verstörende Visionen erneut erlebt\".", completion = "Ich bin froh, dass Ihr unbeschadet zurückgekehrt seid. Ich weiß, dass wir nur weitersuchen müssen, um endlich einen Schlüssel zur Beendigung der Verderbnis der Leere zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89515] = { id = 89515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Strahlen der Flamme", description = "Ihr inspiriert uns weiterhin auf dem Schlachtfeld, {name}. Eure Heldentaten haben unser Volk in diesen schweren Zeiten beschützt, und wir können Euch nicht genug dafür danken.", sourceObjective = "Sprecht mit Lars Bronschmelz in Morgaens Tränen.", completion = "Ich hoffe, Ihr seid weiterhin stolz auf Eure Dienste und nehmt dies hier als kleines Zeichen unserer Anerkennung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[89516] = { id = 89516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Sturm auf die Violette Festung (Normal)", description = "Ein mit mächtigen Artefakten ausgestattetes Team aus Zeitläufern kann viele Gefahren überwinden.\n\nSchauen wir doch mal, ob Ihr diese Version des Sturms auf die Violette Festung meistern könnt.", sourceObjective = "Schließt den Sturm auf die Violette Festung auf dem Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Sehr gute Ergebnisse. Erwartungen übertroffen.", sourceObjectiveStatus = "unverified-source-field" }
