quests[89561] = { id = 89561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingewickelt", description = "Shad'anis hat mir von Euch erzählt. Ein Fleischling mit der Fähigkeit, in den ungebundenen Raum zu reisen. Wie bewerkstelligt Ihr das? Wartet... lasst es mich ableiten.\n \nDas müssen diese Wickel sein, die Ihr als Umhang tragt. Sie wurden durch ein Reshiiband modifiziert. Ich habe so etwas seit dem Verschlingerkrieg nicht mehr gesehen. Sehr schön. Ein Klassiker.\n \nWollt Ihr einen Klassiker? Oder wollt Ihr Macht? Ich kann Eure Reshiiwickel durch moderne technomantische Methoden verbessern, damit Ihr besser für die Gefahren im ungebundenen Raum gewappnet seid.", sourceObjective = "Sprecht mit Hashim über die Reshiiwickel.", progress = "Die Verbesserung der Reshiiwickel ist von höchster Wichtigkeit für Euer Überleben.", completion = "Habt Dank, {name}. Eure Abenteuer im ungebundenen Raum werden uns helfen, den Weg für die Phasentaucher frei zu machen und die Energie zu bergen, die sonst in der Leere verloren gegangen wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[89590] = { id = 89590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Hoffnungsbruch", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch beim Hoffnungsbruch helfen.", sourceObjective = "Schließt den Flügel 'Hoffnungsbruch' von Antorus, dem Brennenden Thron auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89591] = { id = 89591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Sitz des Pantheons", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch beim Sitz des Pantheons helfen.", sourceObjective = "Schließt den Flügel 'Sitz des Pantheons' von Antorus, dem Brennenden Thron auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89592] = { id = 89592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Antorus, der Brennende Thron (Normal)", description = "Einigen Herausforderungen kann man sich nicht allein stellen. Je mehr, desto besser, aber gute Zusammenarbeit ist noch mächtiger.\n\nSchart Eure vertrauenswürdigsten Verbündeten um Euch, um diese Inkarnation von Antorus zu meistern.", sourceObjective = "Besiegt 2 Bosse in Antorus, dem Brennenden Thron auf Schwierigkeitsgrad 'Normal' oder höher.", completion = "Gemeinsam ist alles möglich, sagt man. Offenbar ist da was dran. Hmmm.\n\n<Eternus denkt einen Augenblick nach.>\n\nIch frage mich, welche Sprichwörter noch zutreffen. Das muss in einem Experiment erforscht werden.", sourceObjectiveStatus = "unverified-source-field" }
