quests[89678] = { id = 89678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Bogenaquädukte", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch bei den Bogenaquädukten helfen.", sourceObjective = "Schließt den Flügel 'Bogenaquädukte' der Nachtfestung auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89679] = { id = 89679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Der Smaragdgrüne Alptraum (Heroisch)", description = "Einigen Herausforderungen kann man sich nicht allein stellen. Je mehr, desto besser, aber gute Zusammenarbeit ist noch mächtiger.\n\nSchart Eure vertrauenswürdigsten Verbündeten um Euch, um diese Inkarnation des Smaragdgrünen Alptraums zu meistern.", sourceObjective = "Besiegt 2 Bosse im Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Heroisch' oder höher.", completion = "Gemeinsam ist alles möglich, sagt man. Offenbar ist da was dran. Hmmm.\n\n<Eternus denkt einen Augenblick nach.>\n\nIch frage mich, welche Sprichwörter noch zutreffen. Das muss in einem Experiment erforscht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89680] = { id = 89680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Der Smaragdgrüne Alptraum (Mythisch)", description = "Einigen Herausforderungen kann man sich nicht allein stellen. Je mehr, desto besser, aber gute Zusammenarbeit ist noch mächtiger.\n\nSchart Eure vertrauenswürdigsten Verbündeten um Euch, um diese Inkarnation des Smaragdgrünen Alptraums zu meistern.", sourceObjective = "Besiegt 2 Bosse im Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Mythisch'.", completion = "Gemeinsam ist alles möglich, sagt man. Offenbar ist da was dran. Hmmm.\n\n<Eternus denkt einen Augenblick nach.>\n\nIch frage mich, welche Sprichwörter noch zutreffen. Das muss in einem Experiment erforscht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89681] = { id = 89681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Prüfung der Tapferkeit", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch bei der Prüfung der Tapferkeit helfen.", sourceObjective = "Schließt die Prüfung der Tapferkeit auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[89682] = { id = 89682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Prüfung der Tapferkeit (Normal)", description = "Einigen Herausforderungen kann man sich nicht allein stellen. Je mehr, desto besser, aber gute Zusammenarbeit ist noch mächtiger.\n\nSchart Eure vertrauenswürdigsten Verbündeten um Euch, um diese Inkarnation der Prüfung der Tapferkeit zu meistern.", sourceObjective = "Schließt die Prüfung der Tapferkeit auf dem Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Gemeinsam ist alles möglich, sagt man. Offenbar ist da was dran. Hmmm.\n\n<Eternus denkt einen Augenblick nach.>\n\nIch frage mich, welche Sprichwörter noch zutreffen. Das muss in einem Experiment erforscht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[89683] = { id = 89683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Zeit für Schlachtzüge, Königliches Athenaeum", description = "Wir brauchen Informationen darüber, wie mehrere Zeitläufer und ihre Artefakte interagieren, wenn sie auf Widerstand stoßen.\n\nFindet Mitstreiter, die Euch beim Königlichen Athenaeum helfen.", sourceObjective = "Schließt den Flügel 'Königliches Athenaeum' der Nachtfestung auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Die gesammelte Stärke einer Gruppe aus Zeitläufern mit mächtigen Artefakten ist größer als die Stärke der Individuen. Viel größer als erwartet. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[90081] = { id = 90081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Runensiegel", description = "Ein arkanes Runensiegel ist unerlässlich, um die Authentizität eines Gegenstands als echtes Meisterwerk der Kunsthandwerker des Azurblauen Gewölbes zu belegen. Natürlich können diese Siegel an jedem Gegenstand angebracht werden, um selbst einfachen Flohmarktarttand zu einem kostbaren Kunstwerk zu machen.\n\nIch könnte ein solches Siegel herstellen und damit jede Menge Profit machen. Wenn Ihr zum Azurblauen Gewölbe reist und mir die nötigen Teile besorgt, kann ich es für Euch herstellen.\n\nBringt mir genug Teile für zwei Siegel, dann behalte ich eins als Bezahlung für meine Dienste.", sourceObjective = "Betretet die Tiefe \"Archivangriff\" und sammelt 24 geätzte Fragmente.", progress = "Habt Ihr die Teile gefunden?", completion = "Hervorragend, das ist mehr als genug, um anzufertigen, was Ihr benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90096] = { id = 90096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Taten in der Welt", description = "Überall auf den Verheerten Inseln gibt es Bedürftige. Sie suchen nach Hoffnung und tun sich schwer, welche zu finden. Ihr könnt diese Hoffnung verkörpern.\n\nSucht jene, die auf den Verheerten Inseln in Gefahr sind, und seid der Champion, den sie so dringend benötigen.\n\nSolche Taten formen Legenden.", sourceObjective = "Schließt 4 Weltquests ab.", completion = "Ein einziger heldenhafter Akt kann das Blatt wenden. Ein hoffnungsvolles Flüstern kann die Verzweiflung abwenden. So erhalten Legenden ihre Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[90097] = { id = 90097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Invasionspunkte", description = "Die Legion kämpft nicht auf konventionelle Art und Weise. Sie täuschen, manipulieren und untergraben ihre Gegner wann immer möglich.\n\nDie Legion kennt keine festen Fronten. Sie öffnen einen Riss an einem Schwachpunkt, dann schwärmen sie daraus hervor und verbreiten Tod und Zerstörung. Sie greifen an, wann es ihnen genehm ist.\n\nDoch diese Strategie ist nicht unfehlbar. Mächtige Champions, die schnell reagieren und mobil sind, können diese Invasionen im Keim ersticken. Haltet die Legionsinvasion auf. Zeigt den Leuten, dass die Legion nicht unbesiegbar ist.", sourceObjective = "Schließt einen Legionsinvasionspunkt ab.", completion = "Die Macht, über die Ihr und Euer Artefakt verfügt, konnte einer Invasion der Legion Einhalt gebieten. Doch habt Ihr das bewirkt, oder war es Euer Artefakt? Dazu werde ich weitere Informationen benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90098] = { id = 90098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Große Invasionspunkte", description = "Sobald die Legion Chaos und Verwirrung gestiftet hat, beginnt sie ihren eigentlichen Angriff. Riesige Invasionsrisse öffnen sich und die Legion marschiert in Scharen daraus hervor. Die Verteidiger sind zerstreut und befassen sich mit kleineren Rissen, also sind sie an keinem dieser Orte zahlreich genug vertreten, um die Legion aufzuhalten.\n\nIn solchen Zeiten brauchen wir Champions wie Euch am dringendsten.\n\nSucht Euch eine der großen Invasionen der Legion und bekämpft sie mit allem, was Ihr habt.\n\nZeigt den Leuten, dass man mit genug Entschlossenheit sogar den Weltuntergang aufhalten kann.", sourceObjective = "Schließt einen großen Legionsinvasionspunkt ab.", completion = "Es ist so, wie ich vorhergesagt hatte. Ihr konntet eine gewaltige Invasion der Legion aufhalten. Nicht Ihr habt das vollbracht, und Euer Artefakt auch nicht. Es war die Kombination aus beidem, die siegreich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[90099] = { id = 90099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Selten", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um seltene Gegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 6 seltene Gegner.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90100] = { id = 90100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Seltene Elite", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um seltene Elitegegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 2 seltene Elitegegner.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90101] = { id = 90101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Schrecken der Verheerten Inseln", description = "Es ist an der Zeit, Euch und Euer Artefakt auf die Probe zu stellen.\n\nSucht Euch einen Schrecken der Verheerten Inseln und besiegt ihn.\n\nIch bin mir sicher, dass Ihr uns unabhängig vom Ergebnis viel zu denken geben werdet. Ich werde hochinteressiert zusehen.", sourceObjective = "Tötet einen Weltboss.", completion = "Ein faszinierendes Ergebnis, {name}. Das gewährt uns dringend benötigte Daten für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90102] = { id = 90102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Champion der Verheerten Inseln", description = "Unsere Forschung legt nahe, dass Macht nur ein Teil der Gleichung ist. Es ist auch äußerst bedeutsam, was man damit anfängt.\n\nDie Bewohner der Verheerten Inseln benötigen einen Champion. Kommt ihnen zu Hilfe, vertreibt die Legion von ihren Küsten und Eure Legende wird anwachsen.\n\nWo Ihr anfangt, liegt bei Euch. Die Legion ist überall, Ihr könnt es Euch also beliebig aussuchen.", sourceObjective = "Schließt das Kampagnenkapitel einer beliebigen Zone von Legion ab.", completion = "Eure Legende ist gewachsen, {name}. In der Zeitlinie hallen nicht nur die unmittelbaren Effekte Eurer Taten nach, sondern sie werden potenziert durch die Auswirkungen auf Eure Umgebung. Das ist extrem nützlich für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90103] = { id = 90103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Champion der Ordenshalle", sourceObjective = "Schließt ein Kapitel Eurer Ordenshallenkampagne ab.", completion = "Ihr habt den Respekt erlangt, der Euch als {class} gebührt. Ihr seid ein Anführer. Es bleibt nur noch die Frage, wo es für Euch hingeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[90108] = { id = 90108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Artefaktsammler", description = "Während unserer Untersuchungen dieser Zeitlinie und der Auswirkungen, die Ihr auf sie habt, ist eine Frage aufgekommen: Was wäre anders, wenn Ihr ein anderes Artefakt hättet?\n\nSucht ein neues Artefakt, dann werden wir sehen, ob Eure erste Wahl gut war oder ausgezeichnet.", sourceObjective = "Beschafft Euch eine neue Artefaktwaffe.", completion = "Da habt Ihr ja eine erstaunliche Sammlung, {name}. Alles, was jetzt noch bleibt, ist herauszufinden, ob Ihr einen Liebling unter den Artefakten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90109] = { id = 90109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Saubere Luft", description = "Die Zeit zu manipulieren birgt Risiken, aber eben auch Belohnungen.\n\nDie Strapazierung dieser Zeitlinie hat zahlreiche verweilende Zeitpartikel hervorgebracht, die auf den Verheerten Inseln verteilt sind. Es wäre unverantwortlich, diese nicht zu entfernen.\n\nHier bietet sich aber auch eine Gelegenheit. Wenn Ihr diese Partikel sammelt, dann geht die in ihnen ruhende ewige Macht stattdessen auf Euch über.\n\nWir können also gleichzeitig die Zeitlinie bereinigen und unsere Forschung verbessern.", sourceObjective = "Sammelt im Flug 50 verweilende Zeitpartikel.", completion = "Gut. Es ist nichts Dramatisches passiert, als Ihr die verweilenden Zeitpartikel gesammelt habt. Sagt uns aber Bescheid, falls Ihr ein merkwürdiges Gefühl bekommt.", sourceObjectiveStatus = "unverified-source-field" }
